import{_ as e}from"./chunks/hub.pc.ko.CkqLG1M5.js";import{_ as t}from"./chunks/hub-robots.pc.ko.B1Exws0F.js";import{_ as d}from"./chunks/home-status.pc.ko.BJCyWPnR.js";import{_ as i,o as c,c as a,a5 as r}from"./chunks/framework.D47SInms.js";const n="/RBQ/nightly/images/app/hub-add-robot.pc.ko.png",_=JSON.parse('{"title":"연결","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/connection.md","filePath":"ko/manual/gui/connection.md","lastUpdated":1791600043000}'),l={name:"ko/manual/gui/connection.md"};function s(p,o,h,m,g,u){return c(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="연결" tabindex="-1">연결 <a class="header-anchor" href="#연결" aria-label="Permalink to &quot;연결&quot;">​</a></h1><p><em>앱이 어느 로봇에 붙을지</em>는 <strong>허브</strong>에서 정합니다. 허브는 앱을 켜면 처음 나오는 화면입니다. 왼쪽 위에 로봇 이름과 연결 상태가 있고, 오른쪽 아래 <code>컨트롤</code> 버튼은 로봇이 연결된 뒤에 제어 홈을 엽니다. 연결되기 전에는 <code>연결되면 열립니다</code>로 표시됩니다. 이 화면들에서 로봇으로 보내는 값은 없습니다.</p><p>저장된 로봇도 계정도 없는 첫 실행에서는 허브 대신 <strong>접근 코드</strong> 화면이 열립니다. <code>건너뛰기</code>를 누르면 바로 허브로 가고, 앱이 로봇 망에서 로봇을 스스로 찾습니다.</p><h2 id="상태줄" tabindex="-1">상태줄 <a class="header-anchor" href="#상태줄" aria-label="Permalink to &quot;상태줄&quot;">​</a></h2><p><img src="'+e+'" alt="허브 상태줄"></p><p>로봇 이름 앞에 색 점이, 뒤에 상태가 표시됩니다.</p><table tabindex="0"><thead><tr><th>문구</th><th>의미</th></tr></thead><tbody><tr><td><code>로봇 WiFi에 연결하세요</code></td><td>저장된 로봇이 아직 없습니다</td></tr><tr><td><code>미연결</code></td><td>로봇을 골랐지만 연결되어 있지 않습니다</td></tr><tr><td><code>연결 중…</code></td><td>연결을 시도하고 있습니다</td></tr><tr><td><code>연결됨</code> · 경로</td><td>로봇과 통신 중입니다 — 경로는 <code>로봇망</code>·<code>WAN</code>·<code>원격</code> 중 하나이고 뒤에 배터리가 붙습니다</td></tr><tr><td><code>연결 실패</code> · 이유</td><td>연결에 실패했습니다 — <code>다시 연결</code>을 누르세요</td></tr><tr><td><code>로봇 WiFi가 아닙니다</code></td><td>로봇은 자기 망에 있는데 이 기기는 다른 망에 있습니다</td></tr><tr><td><code>원격 — 접근 코드 필요</code></td><td>원격 로봇을 골랐지만 접근 코드가 저장되어 있지 않습니다 — <code>코드 입력</code>을 누르세요</td></tr></tbody></table><p>기기가 다른 망에 있고 앱이 로봇의 WiFi를 알고 있으면, 어느 망으로 바꿔야 하는지까지 알려 줍니다(<em>로봇 WiFi(SSID)로 바꿔 주세요</em>). Linux 데스크탑과 Steam Deck에서는 옆의 <code>WiFi 전환</code> 버튼이 그 망에 바로 붙거나 망 목록을 엽니다. Android에서는 <code>WiFi 설정</code>이 시스템 Wi-Fi 화면을 엽니다.</p><h2 id="로봇-고르기" tabindex="-1">로봇 고르기 <a class="header-anchor" href="#로봇-고르기" aria-label="Permalink to &quot;로봇 고르기&quot;">​</a></h2><p><img src="'+t+'" alt="로봇 선택"></p><p>로봇 이름(▾)을 탭하면 <strong>로봇 선택</strong>이 열립니다. 이 기기에 저장된 로봇이 나오고, 로그인해 두면 계정에 배정된 로봇도 함께 나옵니다. 양쪽에 다 있는 로봇은 시리얼 번호로 묶어 한 줄로만 보여 줍니다. 각 줄에는 시리얼, 경로(WiFi 이름이 붙은 <code>로봇망</code>, <code>WAN</code>, <code>원격</code>), 마지막으로 쓴 시각이 표시됩니다. 줄을 탭하면 연결합니다.</p><p>줄 앞의 점은 로봇 상태입니다: 초록 = 연결됨, 파랑 = 켜져 있음(로봇 WiFi가 주변에 보임), 회색 = 꺼짐 또는 알 수 없음.</p><ul><li><strong>Linux 데스크탑 · Steam Deck</strong>: 목록을 열 때마다 주변 WiFi를 스캔하고, <code>새로고침</code>으로 다시 스캔합니다. 스캔하는 동안에는 지난 결과 대신 점이 회색으로 남습니다(스캔은 최대 15초 걸립니다). WiFi가 보이지 않는 로봇을 누르면 연결하지 않고 그 줄에 <em>로봇 WiFi 신호가 잡히지 않습니다</em>가 표시됩니다. 로봇의 WiFi가 기기에 저장되어 있고 주변에 보이면 연결하기 전에 그 망으로 옮깁니다. 옮기는 동안 상태줄에 전환 중인 망이 표시됩니다. 옮기지 못하면 창으로 이유를 알리고(<em>로봇 WiFi를 찾을 수 없습니다</em>, <em>WiFi 비밀번호가 필요합니다</em>, <em>로봇 WiFi로 전환하지 못했습니다</em>) 이전 로봇이 그대로 선택됩니다. 비밀번호를 한 번도 넣지 않은 망은 이렇게 옮길 수 없으니 <code>WiFi 선택</code>으로 한 번 붙어 두세요.</li><li><strong>Android · iOS</strong>: 앱이 Wi-Fi를 읽거나 바꿀 수 없어 점은 초록·회색만 표시됩니다. 시스템 설정에서 바꾸세요. 어느 망을 고를지는 상태줄이 알려 줍니다.</li><li>계정에도 배정된 로봇은 로봇망에서 응답하면 직접 연결하고, 응답하지 않으면 원격으로 연결합니다.</li></ul><p>줄의 슬라이더 아이콘을 누르면 그 로봇의 프로필이 열립니다 — <code>이름</code>을 바꾸거나 휴지통 아이콘으로 삭제합니다. 삭제는 이 기기에서만 지우며, 서버 배정은 대시보드에서 관리합니다. 원격 전용 로봇에는 고칠 프로필이 없습니다.</p><p>맨 아래 <code>시뮬레이터</code>(<code>앱 내 물리 시뮬</code>)는 로봇 대신 앱 내 시뮬레이터로 제어 홈을 열고, <code>로봇 추가</code>는 아래 화면을 엽니다.</p><p>시뮬레이터에는 공사현장·산악지대 코스 10개가 있습니다. 아래 도구 줄의 <code>레벨</code>을 누르면 <code>시뮬 레벨</code> 목록이 열리고, 깬 레벨에는 ✓ 와 최고 기록이 붙습니다. 코스는 허공 위에 있어 떨어지면 마지막으로 지난 게이트에서 다시 시작합니다. 게이트를 순서대로 모두 지나 결승 발판에 서면 클리어입니다. 다음 게이트가 밝게 표시되고, 몇 번째인지는 화면 위에 나옵니다. 청록색 게이트는 화살표 방향을 본 채 옆걸음으로 지나야 인정됩니다. 로봇은 늘 걷기 상태라 조이스틱만 밀면 움직이고, 빠르기는 <code>주행</code>의 최고 속도로 정합니다. 시점은 위 가운데 드롭다운에서 <code>3인칭</code>·<code>1인칭 전방</code>·<code>1인칭 후방</code>·<code>계단 뷰</code> 중에 고릅니다. <code>1인칭 전방</code>·<code>1인칭 후방</code>은 로봇 앞·뒤에서 보는 시점이고, <code>계단 뷰</code>는 실기처럼 전방·후방·하부 카메라와 관절 자세를 합친 화면입니다. <code>리셋</code>은 그 레벨을 처음부터 다시 시작합니다.</p><h2 id="로봇-추가" tabindex="-1">로봇 추가 <a class="header-anchor" href="#로봇-추가" aria-label="Permalink to &quot;로봇 추가&quot;">​</a></h2><p><img src="'+n+'" alt="로봇 추가"></p><p><strong>로봇 추가</strong>에서 로봇에 붙는 방법을 고릅니다. 로봇이 응답하면 시리얼 번호로 저장하고 허브로 돌아갑니다.</p><h3 id="로봇-wifi" tabindex="-1">로봇 WiFi <a class="header-anchor" href="#로봇-wifi" aria-label="Permalink to &quot;로봇 WiFi&quot;">​</a></h3><p>로봇의 WiFi(AP)에 붙으면 앱이 로봇을 찾습니다. 로봇 망에서 로봇 주소는 항상 <code>192.168.0.10</code>입니다. 화면을 열 때(이미 로봇에 연결된 경우는 제외)와 <code>다시 확인</code>을 누를 때 확인합니다. 새 로봇의 이름은 찾은 WiFi 이름으로 정해지며, 프로필에서 바꿀 수 있습니다.</p><ul><li><code>WiFi 선택</code>(Linux 데스크탑 · Steam Deck)은 앱 안의 망 목록을 열고, 목록을 닫으면 로봇을 다시 확인합니다. 저장된 망은 붙는 동안 그 줄에 진행 표시와 <code>연결 중…</code>이 나옵니다.</li><li><code>WiFi 설정</code>(Android)은 시스템 Wi-Fi 화면을 엽니다.</li><li>응답이 없으면 <em>로봇이 응답하지 않습니다 — 로봇 전원과 이 기기의 WiFi 가 로봇 AP 인지 확인하세요.</em> 안내가 표시됩니다.</li><li>찾은 로봇이 이미 연결된 로봇이면 다시 추가하지 않고 그 사실을 알려 줍니다 — 다른 로봇의 WiFi로 바꾼 뒤 다시 확인하세요.</li></ul><p>브라우저(웹) 빌드에서는 이 카드에 <em>앱(APK·데스크탑)에서 자동으로 찾습니다.</em> 문구만 표시됩니다.</p><h3 id="주소로-연결" tabindex="-1">주소로 연결 <a class="header-anchor" href="#주소로-연결" aria-label="Permalink to &quot;주소로 연결&quot;">​</a></h3><p>브라우저(웹) 빌드·데스크탑 앱·Steam Deck에는 <strong>주소로 연결</strong>이 함께 나옵니다. 공유기 안쪽에 있는 로봇, 이 PC의 시뮬레이터, 공인 IP를 가진 로봇에 붙을 때 씁니다.</p><ul><li><code>로봇망</code> — <code>로봇 IP</code>를 입력합니다(<code>192.168.0.10</code>이 미리 들어 있습니다). <code>연결</code>은 먼저 그 주소에 로봇이 응답하는지 확인하고, 응답이 없으면 저장하지 않습니다(<em>이 주소에서 로봇이 응답하지 않습니다 — IP 와 로봇 전원을 확인하세요</em>).</li><li><code>로컬</code> — 이 PC 에서 도는 시뮬레이터(<code>127.0.0.1</code>)에 붙습니다. 확인·저장은 <code>로봇망</code>과 같으니 시뮬을 먼저 띄워 두세요. 시뮬을 띄울 수 없는 Steam Deck 에는 나오지 않습니다.</li><li><code>WAN</code> — <code>공인 IP 또는 도메인</code>을 입력합니다. 로봇에 WebRTC 토큰을 설정해 두었다면 <code>WebRTC 토큰 (로봇에 설정한 경우만)</code>에 같은 값을 넣어야 합니다. 사용 중인 망에서 8080·8081 포트로 로봇에 닿을 수 있어야 합니다.</li></ul><p>주소는 프록시를 띄운 그 PC에서 <code>localhost</code>로 열었을 때만 반영됩니다. 다른 기기에서 열면 <em>프록시가 대상을 바꾸지 못했습니다 — 이 PC 에서 localhost 로 열었는지 확인하세요</em>가 표시되니, 프록시를 <code>--robot &lt;새 IP&gt;</code>로 다시 띄우세요.</p><h3 id="접근-코드" tabindex="-1">접근 코드 <a class="header-anchor" href="#접근-코드" aria-label="Permalink to &quot;접근 코드&quot;">​</a></h3><p><code>접근 코드 입력</code>을 누르면 숫자 패드가 열립니다. 대시보드에서 발급한 4자리 코드를 한 번 넣으면 계정에 배정된 로봇이 <strong>로봇 선택</strong>에 들어오고, 이후엔 원격(LTE)으로 붙습니다. 로봇에 공인 IP가 없어도 됩니다.</p><p>오른쪽 위 <strong>프로필</strong> 버튼에서 계정과 <code>배정 로봇</code> 수를 볼 수 있습니다. <code>로그아웃</code>하면 계정의 원격 로봇이 목록에서 빠지고, 이 기기에 저장된 로봇은 남습니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>접근 코드는 인증 정보입니다. 다른 사람과 공유하지 말고, 공용 기기에서는 <code>로그아웃</code>하세요.</p></div><h2 id="자동-연결" tabindex="-1">자동 연결 <a class="header-anchor" href="#자동-연결" aria-label="Permalink to &quot;자동 연결&quot;">​</a></h2><p>다음 경우에는 앱이 스스로 연결합니다.</p><ul><li><strong>앱을 켤 때</strong> — 먼저 로봇 망을 확인합니다. 로봇이 응답하면 목록에 추가(또는 갱신)해 연결하고, 허브를 건너뛰어 제어 홈을 엽니다. 로봇이 없으면 데스크탑 앱(Steam Deck 제외)은 같은 PC에서 돌고 있는 MuJoCo 시뮬레이터에 붙고, 그것도 없으면 최근 로봇을 고릅니다. Linux 데스크탑과 Steam Deck에서는 그 로봇의 WiFi를 알고 기기가 다른 망에 붙어 있으면 옮기기 전에 먼저 묻습니다(<em>로봇 WiFi로 바꿀까요?</em>). <code>WiFi 전환</code>은 로봇 망으로 옮기고, <code>아니오</code>는 지금 망에 그대로 머무릅니다 — 소프트웨어 업데이트 파일을 받는 중이라면 <code>아니오</code>를 고르세요. 한 번 <code>아니오</code>를 고르면 앱을 다시 켤 때까지 자동 연결은 망을 건드리지 않습니다. <strong>로봇 선택</strong>에서 직접 고르면 그때는 옮깁니다.</li><li><strong>망이 바뀔 때</strong> — 기기가 로봇의 WiFi에 붙으면 로봇의 시리얼 번호를 확인해 연결하고, 새 로봇이면 목록에 추가합니다. 원격으로 붙어 있다가 로봇 곁에 오면 이때 직접 연결로 바뀝니다.</li></ul><p>시리얼 번호가 설정되지 않은 로봇도 저장되어 목록에 남습니다. 이런 로봇은 WiFi 이름으로 구분합니다.</p><h2 id="내-기기-wifi" tabindex="-1">내 기기 WiFi <a class="header-anchor" href="#내-기기-wifi" aria-label="Permalink to &quot;내 기기 WiFi&quot;">​</a></h2><p>제어 홈 상단바의 WiFi 칩은 신호 세기를 보여 줍니다. 칩을 탭하면 <strong>내 기기 WiFi</strong>가 열려 이 기기가 붙어 있는 망과, 그 망이 로봇 망인지를 보여 줍니다.</p><ul><li>기기 주소가 로봇 IP와 같은 서브넷이면 <code>로봇 망</code> 배지가 초록으로 뜹니다. 아니면 <code>로봇 망 아님</code> 배지가 주황으로 뜨고, 로봇 AP에 붙기 전에는 로봇에 닿을 수 없다는 경고가 함께 나옵니다. 원격으로 연결된 동안에는 로봇 망을 쓰지 않으니 배지와 경고가 모두 사라집니다.</li><li><strong>Linux 데스크탑 · Steam Deck</strong>: <code>WiFi 선택</code>은 앱 안에서 접속할 망 목록을 열고, <code>시스템 설정</code>은 OS의 네트워크 설정을 대신 엽니다.</li><li><strong>Android</strong>: Android 정책상 앱 안에서 스캔할 수 없으므로 <code>시스템 WiFi 설정</code>이 기기의 Wi-Fi 설정 화면을 엽니다. 목록에서 로봇 AP를 고른 뒤 뒤로 가면 앱으로 돌아옵니다. SSID를 보려면 위치 권한이 있어야 합니다. 안내 문구를 탭하면 권한을 요청합니다. 권한을 줬는데도 이름이 나오지 않으면 기기 위치가 꺼져 있는 것이니, 안내 문구를 탭해 위치를 켜십시오.</li><li>iOS와 웹 빌드에서는 시스템 설정에서 연결하라는 안내가 대신 나옵니다.</li></ul><h2 id="connection-status-in-the-top-bar" tabindex="-1">상단바의 연결 상태 <a class="header-anchor" href="#connection-status-in-the-top-bar" aria-label="Permalink to &quot;상단바의 연결 상태 {#connection-status-in-the-top-bar}&quot;">​</a></h2><p>제어 홈 상단바에서 로고 옆 상태 불빛이 연결 상태를 요약합니다.</p><table tabindex="0"><thead><tr><th>불빛</th><th>의미</th></tr></thead><tbody><tr><td>초록</td><td>정상입니다</td></tr><tr><td>주황</td><td>연결은 됐지만 확인할 것이 있습니다 — 비전 스트림 끊김, 또는 다른 기기가 제어권을 보유</td></tr><tr><td>빨강, 빠르게 깜빡임</td><td>로봇이 이상을 보고하고 있습니다</td></tr><tr><td>빨강</td><td>로봇과 연결되어 있지 않습니다</td></tr></tbody></table><p>불빛을 탭하면 <strong>시스템 종합 상태</strong>가 열립니다. <strong>IMU</strong>, <strong>CAN</strong>, <strong>FindPose</strong>, <strong>Control</strong>, <strong>비전</strong>, <strong>소유권</strong> 항목이 초록·주황 점으로 표시됩니다. <code>실행 ▸</code>이 붙은 항목은 탭해서 그 단계를 다시 실행할 수 있고, <strong>소유권</strong> · <code>가져오기 ▸</code>는 다른 기기가 쥐고 있는 제어권을 가져옵니다.</p><p>제어 홈에는 미연결 배너가 없습니다. 로봇이 끊긴 뒤 8초 안에 돌아오지 않으면 앱이 허브로 넘어갑니다. 상태줄과 <code>다시 연결</code>·<code>WiFi 전환</code>이 모두 허브에 있기 때문입니다. 연결된 로봇이 바뀌는 순간에도 허브로 돌아갑니다 — 로봇을 끄면 그 WiFi가 사라지고, 앱이 로봇망에서 다른 로봇을 찾아 그쪽에 붙을 수 있기 때문입니다.</p><p><img src="'+d+'" alt="시스템 종합 상태"></p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#connection">개발자 모드</a>에 모아 두었습니다.</p></blockquote>',45)])])}const k=i(l,[["render",s]]);export{_ as __pageData,k as default};
